export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=(v,d=2)=>v===null||v===undefined||!Number.isFinite(+v)?'—':(+v).toLocaleString('zh-CN',{maximumFractionDigits:d});
export const units={oil:'标准立方米/日',water:'标准立方米/日',gas:'标准立方米/日',pressure:'兆帕',owr:'标准立方米油/标准立方米水',energy:'千瓦时',watercut:'%',sw:'小数'};
export const titles={oil:'日产油',water:'日产水',gas:'日产气',pressure:'压力',owr:'油水比',sw:'含水饱和度'};
export const colors={oil:'#ac2530',water:'#3088aa',gas:'#8661ac',pressure:'#b98b46',owr:'#2f806e'};
const ok=v=>v!==null&&v!==undefined&&Number.isFinite(+v);
export function lineChart(series,{unit='',labels=[],split=null,band=null,xLabel='日期',height=230}={}){const vals=series.flatMap(s=>s.values.filter(ok)).concat(band?band.low.filter(ok).concat(band.high.filter(ok)):[]);if(!vals.length)return '<div class="empty">无有效数据；缺失值不会填零。</div>';const w=720,h=height,l=65,r=20,t=25,b=38,n=Math.max(...series.map(s=>s.values.length));let lo=Math.min(...vals),hi=Math.max(...vals);if(lo===hi){lo-=.5;hi+=.5;}const pad=(hi-lo)*.12;lo-=pad;hi+=pad;const x=i=>l+i/Math.max(1,n-1)*(w-l-r),y=v=>t+(hi-v)/(hi-lo)*(h-t-b);let svg='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" stroke="#ebe7df"/><text x="${l-9}" y="${y(v)+4}" text-anchor="end">${num(v,Math.abs(v)<2?2:0)}</text>`;}
 if(band){let segment=[];const emit=()=>{if(segment.length>1)svg+=`<polygon points="${segment.map(i=>`${x(i)},${y(band.high[i])}`).concat([...segment].reverse().map(i=>`${x(i)},${y(band.low[i])}`)).join(' ')}" fill="#577caa" opacity=".13"/>`;segment=[];};for(let i=0;i<n;i++){if(ok(band.low[i])&&ok(band.high[i]))segment.push(i);else emit();}emit();}
 if(split!==null)svg+=`<line x1="${x(split)}" x2="${x(split)}" y1="${t}" y2="${h-b}" stroke="#a59c90" stroke-dasharray="3 4"/><text x="${x(split)+6}" y="${t+10}">预测起点</text>`;
 for(const s of series){let d='',active=false;for(let i=0;i<s.values.length;i++){const v=s.values[i];if(!ok(v)){active=false;continue;}d+=`${active?'L':'M'}${x(i)},${y(v)} `;active=true;}svg+=`<path d="${d}" fill="none" stroke="${s.color??'#ac2530'}" stroke-width="2" ${s.dash?'stroke-dasharray="6 4"':''}/>`;}
 svg+=`<text x="${l}" y="12">${esc(unit)}</text>`;for(const i of [...new Set([0,Math.floor((n-1)/2),n-1])])svg+=`<text x="${x(i)}" y="${h-13}" text-anchor="middle">${esc(labels[i]??i+1)}</text>`;
 return `<div class="chart-box"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.name).join('、'))}；${esc(unit)}">${svg}</svg><div class="legend">${series.map(s=>`<span><i class="${s.dash?'dash':''}" style="background:${s.color};color:${s.color}"></i>${esc(s.name)}</span>`).join('')}${band?'<span><i style="background:#d8e0eb;height:9px"></i>残差模拟P10—P90</span>':''}</div><div class="unit-note">横轴：${esc(xLabel)}；纵轴：${esc(unit)}。空值断线；不同单位分别作图。</div></div>`;
}
export const panel=(title,body,extra='',note='')=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${extra}</div><div class="panel-body">${body}</div>${note?`<div class="panel-note">${note}</div>`:''}</section>`;
export function table(rows,columns,limit=30){return `<div class="wide-table"><table><thead><tr>${columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${columns.map(([key,,d])=>`<td>${typeof r[key]==='number'?num(r[key],d??3):esc(r[key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export const flow=steps=>`<div class="flow">${steps.map((s,i)=>`${i?'<span class="arrow">→</span>':''}<span class="step">${esc(s)}</span>`).join('')}</div>`;
export const conclusion=s=>`<div class="conclusion"><strong>分析与结论</strong>　${s}</div>`;
export function scatter(rows,{xKey='oil',yKey='energy',xName='累计产油（标准立方米）',yName='累计能耗（千瓦时）',selectable=false}={}){if(!rows.length)return '<div class="empty">尚无可行解。请检查压力、功率与变量边界。</div>';const xs=rows.map(p=>p[xKey]),ys=rows.map(p=>p[yKey]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),x=v=>65+(v-xmin)/Math.max(1e-9,xmax-xmin)*620,y=v=>220-(v-ymin)/Math.max(1e-9,ymax-ymin)*170;return `<div class="chart-box"><svg viewBox="0 0 730 280" role="img" aria-label="${esc(xName)}与${esc(yName)}散点图"><path d="M65 30V230H705" fill="none" stroke="#c8c1b4"/>${[0,.5,1].map(q=>`<text x="${65+620*q}" y="250" text-anchor="middle">${num(xmin+(xmax-xmin)*q,0)}</text><text x="58" y="${224-q*170}" text-anchor="end">${num(ymin+(ymax-ymin)*q,0)}</text>`).join('')}<text x="65" y="15">${esc(yName)}</text><text x="390" y="275" text-anchor="middle">${esc(xName)}</text>${rows.map((r,i)=>`<circle ${selectable?`data-pick="${i}" tabindex="0" role="button" class="point" aria-label="选择方案${i+1}"`:''} cx="${x(r[xKey])}" cy="${y(r[yKey])}" r="5" fill="#b88a4e" stroke="#fff"><title>方案${i+1}：${esc(xName)} ${num(r[xKey])}；${esc(yName)} ${num(r[yKey])}</title></circle>`).join('')}</svg></div>`;}
export function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';return '\uFEFF'+[keys.map(q).join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\n');}
export function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
